#[test]
fn test_bytea_functions_on_out_of_band_values() {
    run_scripts(&[
        ScriptTest {
            name: "bytea functions on out-of-band values",
            set_up_script: &[
                "create table t_bytes (id int primary key, body bytea);",
                r#"insert into t_bytes values (1, '\');"#,
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "select body from t_bytes;",
                    expected: Expected::Rows {
                        columns: &[Column("body", BYTEA)],
                        rows: &[
                            &[T(r#"\"#)],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select octet_length(body), length(body), bit_length(body) from t_bytes;",
                    expected: Expected::Rows {
                        columns: &[Column("octet_length", INT4), Column("length", INT4), Column("bit_length", INT4)],
                        rows: &[
                            &[T("20000"), T("20000"), T("160000")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select length(encode(body, 'hex')) from t_bytes;",
                    expected: Expected::Rows {
                        columns: &[Column("length", INT4)],
                        rows: &[
                            &[T("40000")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select left(encode(body, 'hex'), 4) from t_bytes;",
                    expected: Expected::Rows {
                        columns: &[Column("left", TEXT)],
                        rows: &[
                            &[T("7878")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"select length(encode(body || '\x79', 'hex')) from t_bytes;"#,
                    expected: Expected::Rows {
                        columns: &[Column("length", INT4)],
                        rows: &[
                            &[T("40002")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"select body = '\' from t_bytes;"#,
                    expected: Expected::Rows {
                        columns: &[Column("?column?", BOOL)],
                        rows: &[
                            &[T("t")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"select body <= '\x79', body <> '\x78', body >= '\x78' from t_bytes;"#,
                    expected: Expected::Rows {
                        columns: &[Column("?column?", BOOL), Column("?column?", BOOL), Column("?column?", BOOL)],
                        rows: &[
                            &[T("t"), T("t"), T("t")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"select byteacmp(body, '\x79') from t_bytes;"#,
                    expected: Expected::Rows {
                        columns: &[Column("byteacmp", INT4)],
                        rows: &[
                            &[T("-1")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
fn test_string_functions_on_out_of_band_values() {
    run_scripts(&[
        ScriptTest {
            name: "string functions on out-of-band values",
            set_up_script: &[
                "create table t_big (id int primary key, body varchar);",
                "insert into t_big values (1, repeat('x', 20000));",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "select length(body) from t_big;",
                    expected: Expected::Rows {
                        columns: &[Column("length", INT4)],
                        rows: &[
                            &[T("20000")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select length(replace(body, 'x', 'y')) from t_big;",
                    expected: Expected::Rows {
                        columns: &[Column("length", INT4)],
                        rows: &[
                            &[T("20000")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select length(upper(body)), length(lower(body)) from t_big;",
                    expected: Expected::Rows {
                        columns: &[Column("length", INT4), Column("length", INT4)],
                        rows: &[
                            &[T("20000"), T("20000")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select left(body, 3), right(body, 3) from t_big;",
                    expected: Expected::Rows {
                        columns: &[Column("left", TEXT), Column("right", TEXT)],
                        rows: &[
                            &[T("xxx"), T("xxx")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select ascii(body) from t_big;",
                    expected: Expected::Rows {
                        columns: &[Column("ascii", INT4)],
                        rows: &[
                            &[T("120")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select strpos(body, 'x') from t_big;",
                    expected: Expected::Rows {
                        columns: &[Column("strpos", INT4)],
                        rows: &[
                            &[T("1")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select length(reverse(body)) from t_big;",
                    expected: Expected::Rows {
                        columns: &[Column("length", INT4)],
                        rows: &[
                            &[T("20000")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select length(translate(body, 'x', 'z')) from t_big;",
                    expected: Expected::Rows {
                        columns: &[Column("length", INT4)],
                        rows: &[
                            &[T("20000")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select length(ltrim(body, 'x')), length(rtrim(body, 'x')), length(btrim(body, 'x')) from t_big;",
                    expected: Expected::Rows {
                        columns: &[Column("length", INT4), Column("length", INT4), Column("length", INT4)],
                        rows: &[
                            &[T("0"), T("0"), T("0")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select length(split_part(body, ',', 1)) from t_big;",
                    expected: Expected::Rows {
                        columns: &[Column("length", INT4)],
                        rows: &[
                            &[T("20000")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select length(repeat(body, 1)) from t_big;",
                    expected: Expected::Rows {
                        columns: &[Column("length", INT4)],
                        rows: &[
                            &[T("20000")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select md5(body) from t_big;",
                    expected: Expected::Rows {
                        columns: &[Column("md5", TEXT)],
                        rows: &[
                            &[T("e5d2c6fe7777b38038eb8315e1f5c734")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select octet_length(body), bit_length(body) from t_big;",
                    expected: Expected::Rows {
                        columns: &[Column("octet_length", INT4), Column("bit_length", INT4)],
                        rows: &[
                            &[T("20000"), T("160000")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select initcap(left(body, 3)) from t_big;",
                    expected: Expected::Rows {
                        columns: &[Column("initcap", TEXT)],
                        rows: &[
                            &[T("Xxx")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select body::varchar(5) from t_big;",
                    expected: Expected::Rows {
                        columns: &[Column("body", VARCHAR)],
                        rows: &[
                            &[T("xxxxx")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select length(body || 'y') from t_big;",
                    expected: Expected::Rows {
                        columns: &[Column("length", INT4)],
                        rows: &[
                            &[T("20001")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select body = repeat('x', 20000) from t_big;",
                    expected: Expected::Rows {
                        columns: &[Column("?column?", BOOL)],
                        rows: &[
                            &[T("t")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "select body < repeat('y', 5) from t_big;",
                    expected: Expected::Rows {
                        columns: &[Column("?column?", BOOL)],
                        rows: &[
                            &[T("t")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

